import{_ as a,o as n,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const m=JSON.parse('{"title":"前端中的e2e测试","description":"","frontmatter":{"title":"前端中的e2e测试","date":"2019-04-06 12:12","comments":true,"archives":2019,"tags":["e2e","test"]},"headers":[],"relativePath":"posts/2019-04-06-javascript-e2e-test/index.md","filePath":"posts/2019/2019-04-06-javascript-e2e-test.md"}'),p={name:"posts/2019-04-06-javascript-e2e-test/index.md"};function r(o,s,t,c,i,u){return n(),e("div",null,[...s[0]||(s[0]=[l(`<p>对于单页面应用，我们需要由前端来控制每个页面的路由。但是在开发过程中，我们经常要对路由进行调整。每次调整都要手动检查所有页面是否正常显示。这个过程实在是太浪费生命了， 所以我们需要选择一个测试框架来自动完成这个过程，结合 CI 系统，在每次 PR 的时候都自动测试一遍，只有通过测试才会进行下一步的 review。</p><h2 id="nightwatch" tabindex="-1">Nightwatch <a class="header-anchor" href="#nightwatch" aria-label="Permalink to &quot;Nightwatch&quot;">​</a></h2><p>Nightwatch 是基于<a href="https://www.w3.org/TR/webdriver/" target="_blank" rel="noreferrer">W3C WebDriver API</a>。WebDrive 主要是为了满足浏览器的自动化测试需求，把最终的接口统一成 HTTP 协议。 所以可以统一不同浏览器的自动化测试接口。我们只要安装每个浏览器的 WebDriver 实现，就可以同一套代码在不同的浏览器中进行测试。老版本的 NightWatch 需要使用 Selenium 来管理各个浏览器，但是从 1.0 版本开始便不需要也不推荐。所以我现在的项目中并没有安装 Selenium。</p><h2 id="依赖" tabindex="-1">依赖 <a class="header-anchor" href="#依赖" aria-label="Permalink to &quot;依赖&quot;">​</a></h2><p>由于不需要安装 Selenium，所以并不需要安装 Java 依赖。我使用 Chrome 浏览器来进行自动化测试，所以需要测试环境安装 Chrome，注意安装的必须是 Chrome，Chromium 不可以。 在 Travis CI 中可以很方便的添加<a href="https://docs.travis-ci.com/user/chrome" target="_blank" rel="noreferrer">Chrome</a>。还需要安装 ChromeDriver 依赖来驱动 Chrome 完成自动化测试。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>在 Linux 测试环境下，基本上都是没有图形化界面的，所以我们在配置 Chrome 的启动参数中需要加入<code>--headless</code>选项，这样就可以不启动 UI。当我们以 root 权限启动的时候还需要添加<code>--no-sandbox</code>选项，这两个选项基本上是必须的。在我的实际情况下，需要测试不同 UA 下的展示效果，所以还需要添加<code>--user-agent=Mozilla/5.0 (Macintosh; Test</code>自定义的 UA。 下面给出一个配置的例子供大家参考：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">    // http://nightwatchjs.org/gettingstarted#settings-file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#005CC5;">    module</span><span style="color:#24292E;">.</span><span style="color:#005CC5;">exports</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#24292E;">      output_folder: </span><span style="color:#032F62;">&quot;tests/e2e/reports&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">      custom_assertions_path: [</span><span style="color:#032F62;">&quot;tests/e2e/custom-assertions&quot;</span><span style="color:#24292E;">],</span></span>
<span class="line"><span style="color:#24292E;">      globals_path: </span><span style="color:#032F62;">&quot;globalsModule.js&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">      src_folders: [</span><span style="color:#032F62;">&quot;tests/e2e/specs/web&quot;</span><span style="color:#24292E;">]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">      webdriver: {</span></span>
<span class="line"><span style="color:#24292E;">        start_process: </span><span style="color:#005CC5;">true</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">        server_path: </span><span style="color:#6F42C1;">require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;chromedriver&quot;</span><span style="color:#24292E;">).path,</span></span>
<span class="line"><span style="color:#24292E;">        cli_args: [</span><span style="color:#032F62;">&quot;--verbose&quot;</span><span style="color:#24292E;">],</span></span>
<span class="line"><span style="color:#24292E;">        port: </span><span style="color:#005CC5;">9515</span></span>
<span class="line"><span style="color:#24292E;">      },</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">      test_settings: {</span></span>
<span class="line"><span style="color:#24292E;">        default: {</span></span>
<span class="line"><span style="color:#24292E;">          desiredCapabilities: {</span></span>
<span class="line"><span style="color:#24292E;">            browserName: </span><span style="color:#032F62;">&quot;chrome&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">            javascriptEnabled: </span><span style="color:#005CC5;">true</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">            chromeOptions: {</span></span>
<span class="line"><span style="color:#24292E;">              args: [</span><span style="color:#032F62;">&quot;--headless&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;--no-sandbox&quot;</span><span style="color:#24292E;">]</span></span>
<span class="line"><span style="color:#24292E;">            },</span></span>
<span class="line"><span style="color:#24292E;">            acceptSslCerts: </span><span style="color:#005CC5;">true</span></span>
<span class="line"><span style="color:#24292E;">          }</span></span>
<span class="line"><span style="color:#24292E;">        }</span></span>
<span class="line"><span style="color:#24292E;">      }</span></span>
<span class="line"><span style="color:#24292E;">    };</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><p>每个参数的详细含义可以参考官方的说明文档。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在集成 Nightwatch 的时候，我是卡在了安装浏览器上。在 Mac 系统上可以正常执行，在 CentOS 的 docker 里面却不行。找了半天发现是自己用了 Chromium，之前对 Chromium 能代替 Chrome 深信不疑。。。 在遇到问题的时候，还是多怀疑，多找找可能性比较好。</p>`,11)])])}const h=a(p,[["render",r]]);export{m as __pageData,h as default};
